def render(context):
    exec(compile('st.header(\n    "EV Adoption & Charging Infrastructure Gap Analysis"\n)\nst.markdown(\n    "Comparative analysis of state-wise EV registrations "\n    "and operational public charging infrastructure across India."\n)\nanalysis_df = df.copy()\nanalysis_df["state_key"] = normalize_state(\n    analysis_df["state"]\n)\nvahan_working = vahan_df.copy()\nvahan_working["state_key"] = normalize_state(\n    vahan_working["state"]\n)\nif analysis_df["state_key"].duplicated().any():\n\n    st.error(\n        "Duplicate normalized state names in infrastructure data."\n    )\n\n    st.stop()\nif vahan_working["state_key"].duplicated().any():\n\n    st.error(\n        "Duplicate normalized state names in VAHAN data."\n    )\n\n    st.stop()\nmerged_df = analysis_df.merge(\n    vahan_working[\n        [\n            "state_key",\n            "annual_ev_registrations",\n            "financial_year",\n        ]\n    ],\n    on="state_key",\n    how="left",\n    validate="one_to_one",\n    indicator=True,\n)\nunmatched = merged_df.loc[\n    merged_df["_merge"] != "both",\n    "state",\n].tolist()\nmatched_df = merged_df.loc[\n    merged_df["_merge"] == "both"\n].copy()\nmatched_df.drop(\n    columns=[\n        "_merge",\n        "state_key",\n    ],\n    inplace=True,\n)\nif unmatched:\n\n    st.warning(\n        "Some infrastructure states could not be matched "\n        f"with VAHAN: {unmatched}. Check source naming."\n    )\nif matched_df.empty:\n\n    st.error(\n        "No matching states found between the two datasets."\n    )\n\n    st.stop()\nmatched_df["operationalization_rate"] = np.where(\n    matched_df["installed_total"] > 0,\n    (\n        matched_df["operational"]\n        / matched_df["installed_total"]\n    ) * 100,\n    np.nan,\n)\nmatched_df["installed_not_operational"] = (\n    matched_df["installed_total"]\n    - matched_df["operational"]\n)\nmatched_df["annual_registrations_per_charger"] = np.where(\n    matched_df["operational"] > 0,\n    (\n        matched_df["annual_ev_registrations"]\n        / matched_df["operational"]\n    ),\n    np.nan,\n)\nvalid_ratios = matched_df[\n    "annual_registrations_per_charger"\n].dropna()\nif valid_ratios.empty:\n\n    st.error(\n        "Unable to calculate infrastructure pressure indicators."\n    )\n\n    st.stop()\nmedian_ratio = valid_ratios.median()\nmatched_df["relative_pressure_index"] = (\n    matched_df["annual_registrations_per_charger"]\n    / median_ratio\n)\nmatched_df["relative_pressure"] = np.select(\n    [\n        matched_df["relative_pressure_index"] > 1.25,\n\n        matched_df["relative_pressure_index"] >= 0.75,\n    ],\n    [\n        "Higher relative pressure",\n\n        "Near median",\n    ],\n    default="Lower relative pressure",\n)\nst.info(\n    "VAHAN source: FY 2024-25 annual EV registrations. "\n    "Infrastructure source: Ministry of Heavy Industries / "\n    "OMC reported charger counts as on 1 March 2026. "\n    "Annual registrations are not cumulative active EV stock. "\n    "These indicators describe relative annual registration "\n    "pressure per operational charger, not an official or "\n    "definitive infrastructure shortage."\n)\nst.subheader(\n    "India EV Infrastructure Indicators"\n)\ntotal_registrations = int(\n    matched_df["annual_ev_registrations"].sum()\n)\nmatched_operational = int(\n    matched_df["operational"].sum()\n)\nmatched_installed = int(\n    matched_df["installed_total"].sum()\n)\nk1, k2, k3, k4 = st.columns(4)\nk1.metric(\n    "Matched States / UTs",\n    f"{len(matched_df)}",\n)\nk2.metric(\n    "Annual EV Registrations",\n    f"{total_registrations:,}",\n)\nk3.metric(\n    "Operational Chargers",\n    f"{matched_operational:,}",\n)\nk4.metric(\n    "National Registrations / Charger",\n    (\n        f"{total_registrations / matched_operational:.1f}"\n        if matched_operational > 0\n        else "N/A"\n    ),\n)\nst.caption(\n    "The national indicator is a ratio of annual registrations "\n    "to operational chargers, not an EV ownership ratio."\n)\nst.subheader(\n    "State-wise EV Registrations"\n)\nregistration_df = matched_df.nlargest(\n    15,\n    "annual_ev_registrations",\n).sort_values(\n    "annual_ev_registrations",\n    ascending=True,\n)\nregistration_chart = px.bar(\n    registration_df,\n    x="annual_ev_registrations",\n    y="state",\n    orientation="h",\n    color="annual_ev_registrations",\n    title=(\n        "Top 15 States / UTs by Annual EV Registrations"\n    ),\n    labels={\n        "annual_ev_registrations": "EV Registrations",\n        "state": "State / UT",\n    },\n    text_auto=",",\n)\nst.plotly_chart(\n    registration_chart,\n    width="stretch",\n)\nst.subheader(\n    "EV Adoption vs Charging Infrastructure"\n)\nscatter_chart = px.scatter(\n    matched_df,\n    x="operational",\n    y="annual_ev_registrations",\n    hover_name="state",\n    size="annual_ev_registrations",\n    color="relative_pressure",\n    title=(\n        "Annual EV Registrations vs Operational Chargers"\n    ),\n    labels={\n        "operational": "Operational Chargers",\n        "annual_ev_registrations": "Annual EV Registrations",\n        "relative_pressure": "Relative Pressure",\n    },\n)\nst.plotly_chart(\n    scatter_chart,\n    width="stretch",\n)\nst.subheader(\n    "Relative Infrastructure Pressure by State"\n)\npressure_df = matched_df.dropna(\n    subset=[\n        "annual_registrations_per_charger"\n    ]\n).sort_values(\n    "annual_registrations_per_charger",\n    ascending=False,\n)\npressure_chart = px.bar(\n    pressure_df.head(15).sort_values(\n        "annual_registrations_per_charger"\n    ),\n    x="annual_registrations_per_charger",\n    y="state",\n    orientation="h",\n    color="relative_pressure",\n    title=(\n        "Top 15 States by Annual Registrations "\n        "per Operational Charger"\n    ),\n    labels={\n        "annual_registrations_per_charger":\n            "Annual Registrations per Charger",\n\n        "state": "State / UT",\n    },\n)\nst.plotly_chart(\n    pressure_chart,\n    width="stretch",\n)\nst.caption(\n    f"Relative benchmark: median of matched state-level ratios "\n    f"({median_ratio:.2f} annual registrations per charger). "\n    "A higher ratio indicates greater relative pressure, "\n    "not a measured shortage."\n)\nst.subheader(\n    "Charging Infrastructure Operationalization"\n)\nrate_df = matched_df.sort_values(\n    "operationalization_rate",\n    na_position="first",\n)\nrate_chart = px.bar(\n    rate_df,\n    x="operationalization_rate",\n    y="state",\n    orientation="h",\n    title=(\n        "Operational Chargers as Percentage "\n        "of Net Installations"\n    ),\n    labels={\n        "operationalization_rate":\n            "Operationalization Rate (%)",\n\n        "state": "State / UT",\n    },\n)\nst.plotly_chart(\n    rate_chart,\n    width="stretch",\n)\nst.subheader(\n    "Combined State-wise Dataset"\n)\ndisplay_columns = [\n    "state",\n    "annual_ev_registrations",\n    "installed_total",\n    "operational",\n    "annual_registrations_per_charger",\n    "relative_pressure_index",\n    "relative_pressure",\n    "operationalization_rate",\n]\nfinal_table = matched_df[\n    display_columns\n].sort_values(\n    "annual_registrations_per_charger",\n    ascending=False,\n    na_position="last",\n)\nst.dataframe(\n    final_table.round(2),\n    width="stretch",\n    hide_index=True,\n)\ncsv_data = final_table.to_csv(\n    index=False\n).encode("utf-8")\nst.download_button(\n    label="Download Combined Analysis CSV",\n    data=csv_data,\n    file_name="EVChargeIQ_Combined_Analysis.csv",\n    mime="text/csv",\n)\nst.success(\n    "VAHAN and charging infrastructure datasets "\n    "successfully integrated."\n)', __file__, 'exec'), context)
